package com.shilapi.xcertplay;
import android.content.Context;import android.graphics.SurfaceTexture;import android.opengl.*;import android.view.Surface;
import java.util.concurrent.*;import java.util.function.BooleanSupplier;
public final class GlCheck {
 static int checks;static long pts;
 static long read(E01GlOutput o,String n)throws Exception{java.lang.reflect.Field f=E01GlOutput.class.getDeclaredField(n);f.setAccessible(true);return ((Number)f.get(o)).longValue();}
 static void setReport(E01GlOutput o)throws Exception{java.lang.reflect.Field f=E01GlOutput.class.getDeclaredField("reports");f.setAccessible(true);f.setInt(o,3);}
 static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static void await(BooleanSupplier b,String m)throws Exception{long end=System.nanoTime()+3000000000L;while(!b.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(3);ok(b.getAsBoolean(),m);}
 static final class Callback implements E01GlOutput.Callback {volatile Surface input;volatile Throwable error;volatile int ready,failed;volatile boolean failedWhileWindowConnected;public void ready(Surface s){input=s;ready++;}public void failed(Throwable e){error=e;failed++;failedWhileWindowConnected=FakeGpu.activeWindows.get()!=0;}}
 static final class Run{final Callback callback=new Callback();final Surface window=new Surface();final E01GlOutput out=new E01GlOutput(new Context(),window,callback);Run()throws Exception{out.resizeWindow(1920,720);out.setFormat(1920,720,60);await(()->callback.ready==1||callback.failed>0,"ready callback");if(callback.error!=null)throw new AssertionError(callback.error);}void emit(int n,long gap)throws Exception{for(int i=0;i<n;i++){callback.input.texture.emit(++pts);Thread.sleep(gap);}}void done()throws Exception{out.close();await(()->callback.input.texture.released,"consumer released");await(()->FakeGpu.activeContexts.get()==0,"contexts released");ok(FakeGpu.textures.isEmpty(),"textures released");ok(FakeGpu.hazards.get()==0,"no texture GPU ownership violation");ok(window.released==0,"bridge never releases holder-owned Surface");}}
 public static void main(String[]args)throws Exception {
  FakeGpu.reset();Run normal=new Run();normal.emit(16,20);await(()->FakeGpu.swapped.get()>8,"continuous frames presented");Thread.sleep(100);int stable=FakeGpu.swapped.get();Thread.sleep(100);ok(stable==FakeGpu.swapped.get(),"no new frame: no stale READY replay or duplicate swaps");synchronized(normal.out.lock){setReport(normal.out);}normal.out.setFormat(1920,720,60);ok(read(normal.out,"reports")==0&&read(normal.out,"reportAt")==0,"same-format configure re-arms bounded report windows");ok(read(normal.out,"reportUpdated")==read(normal.out,"updated")&&read(normal.out,"reportCopied")==read(normal.out,"copied")&&read(normal.out,"reportSwapped")==read(normal.out,"swapped"),"new report windows baseline cumulative counters");normal.emit(1,20);ok(read(normal.out,"reportAt")>0,"new logging window starts at first new frame");normal.done();ok(normal.callback.failed==0,"normal close not failure");
  FakeGpu.reset();Run stalled=new Run();stalled.out.retainCodec();FakeGpu.blockSwap=true;stalled.emit(1,40);ok(FakeGpu.swapped.get()==0,"window swap is blocked");int start=FakeGpu.consumed.get();stalled.emit(30,3);await(()->FakeGpu.consumed.get()>=start+25,"consumer drains while display swap blocked");ok(FakeGpu.textures.size()<=4,"bounded three RGBA plus OES textures");int before=FakeGpu.copied.get();ok(before>15,"copies continue independently of swap");long close=System.nanoTime();stalled.out.close();ok(System.nanoTime()-close<100000000L,"close does not block UI on swap");ok(!stalled.callback.input.texture.released,"codec-owned input survives closing");FakeGpu.releaseSwap();await(()->FakeGpu.activeWindows.get()==0,"window disconnected before input cleanup");ok(!stalled.callback.input.texture.released,"input retained until codec release");stalled.out.releaseCodec();await(()->stalled.callback.input.texture.released,"input released after codec ownership ends");await(()->FakeGpu.activeContexts.get()==0,"closed contexts after delayed swap");ok(FakeGpu.hazards.get()==0,"no overwrite during stalled swap");
  FakeGpu.reset();Run latest=new Run();FakeGpu.blockSwap=true;latest.emit(1,40);latest.emit(20,3);Thread.sleep(30);FakeGpu.releaseSwap();await(()->FakeGpu.swapped.get()>=2,"latest pending frame displayed after stall");Thread.sleep(120);ok(FakeGpu.swapped.get()==2,"does not replay older READY frames after newest");latest.done();
  FakeGpu.reset();Run held=new Run();FakeGpu.holdReadFences=true;held.emit(8,25);int copies=FakeGpu.copied.get(),updates=FakeGpu.consumed.get();held.emit(12,3);await(()->FakeGpu.consumed.get()>=updates+10,"all GPU slots busy: consumer keeps updating");ok(FakeGpu.copied.get()==copies,"busy GPU textures are not overwritten");FakeGpu.releaseFences();held.emit(3,25);ok(FakeGpu.copied.get()>copies,"signaled display fences allow reuse");FakeGpu.holdReadFences=false;held.done();
  FakeGpu.reset();Run resized=new Run();FakeGpu.blockSwap=true;resized.emit(1,40);resized.emit(8,3);Thread.sleep(30);resized.out.setFormat(1280,480,30);FakeGpu.releaseSwap();await(()->FakeGpu.swapped.get()==1,"old already-drawn swap finishes");Thread.sleep(120);ok(FakeGpu.swapped.get()==1,"format change discards all old READY images");resized.emit(5,40);await(()->FakeGpu.swapped.get()>3,"new format resumes rendering");resized.done();
  FakeGpu.reset();Run changedWhileCopy=new Run();FakeGpu.blockCopy=true;changedWhileCopy.emit(1,3);await(()->FakeGpu.blockedCopies.get()>0,"copy in progress");long formatStart=System.nanoTime();changedWhileCopy.out.setFormat(1280,480,30);ok(System.nanoTime()-formatStart<100000000L,"setFormat does not wait for GL copy lock");FakeGpu.releaseCopy();Thread.sleep(100);ok(FakeGpu.swapped.get()==0,"old-generation WRITING never published after format change");changedWhileCopy.emit(3,40);await(()->FakeGpu.swapped.get()>0,"new generation renders after in-flight resize");changedWhileCopy.done();
  FakeGpu.reset();Run sameFormat=new Run();FakeGpu.blockSwap=true;sameFormat.emit(1,40);sameFormat.emit(8,3);Thread.sleep(25);sameFormat.out.setFormat(1920,720,60);FakeGpu.releaseSwap();await(()->FakeGpu.swapped.get()==1,"previous same-format draw completes");Thread.sleep(100);ok(FakeGpu.swapped.get()==1,"new codec with identical format clears old READY");sameFormat.emit(2,30);await(()->FakeGpu.swapped.get()>1,"identical format reconfigure resumes");sameFormat.done();
  FakeGpu.reset();Run sameWriting=new Run();FakeGpu.blockCopy=true;sameWriting.emit(1,3);await(()->FakeGpu.blockedCopies.get()>0,"same-format copy in flight");sameWriting.out.setFormat(1920,720,60);FakeGpu.releaseCopy();Thread.sleep(100);ok(FakeGpu.swapped.get()==0,"identical format reconfigure discards old WRITING");sameWriting.emit(2,30);await(()->FakeGpu.swapped.get()>0,"identical format new frames render");sameWriting.done();
  FakeGpu.reset();FakeGpu.es3=false;Run es2=new Run();es2.emit(12,20);await(()->FakeGpu.swapped.get()>5,"ES2 fallback renders");ok(FakeGpu.finishes.get()>5,"ES2 completes local work before handing off texture");es2.done();
  FakeGpu.reset();Run failure=new Run();failure.out.retainCodec();failure.out.abort(new IllegalStateException("synthetic"));await(()->failure.callback.failed==1,"failed callback not blocked by live codec ref");ok(!failure.callback.failedWhileWindowConnected,"fallback notified only after window EGL disconnect");ok(!failure.callback.input.texture.released,"failed bridge retains codec input");failure.out.releaseCodec();await(()->failure.callback.input.texture.released,"failed input released after codec");ok(failure.callback.failed==1,"failure once");
  FakeGpu.reset();Run brokenConsumer=new Run();brokenConsumer.out.retainCodec();FakeGpu.failUpdate=true;brokenConsumer.emit(1,5);await(()->brokenConsumer.callback.failed==1,"consumer failure reported after display detach");await(()->brokenConsumer.callback.input.texture.released,"fatal consumer abandons input before codec release");ok(FakeGpu.activeContexts.get()>0,"shared resources held until codec ref ends");ok(!brokenConsumer.callback.failedWhileWindowConnected,"fatal fallback notified after window disconnect");Thread nativeStop=new Thread(()->{while(!brokenConsumer.callback.input.texture.released)Thread.yield();brokenConsumer.out.releaseCodec();},"fake-native-stop");nativeStop.start();nativeStop.join(1000);ok(!nativeStop.isAlive(),"native release waiting on abandoned input does not deadlock");await(()->FakeGpu.activeContexts.get()==0,"fatal consumer finally releases contexts");ok(FakeGpu.textures.isEmpty(),"fatal consumer texture cleanup");
  FakeGpu.reset();Run fenceFailure=new Run();FakeGpu.failCopyFence=true;fenceFailure.emit(1,5);await(()->fenceFailure.callback.failed==1,"error after producer fence creation reported");await(()->FakeGpu.activeContexts.get()==0,"post-fence failure cleans contexts");ok(FakeGpu.fenceCount()==0,"producer fence survives error for later cleanup, no sync leak");ok(FakeGpu.textures.isEmpty(),"post-fence failure cleans all textures");
  FakeGpu.reset();FakeGpu.failInit=true;Callback bad=new Callback();E01GlOutput invalid=new E01GlOutput(new Context(),new Surface(),bad);await(()->bad.failed==1,"initialization failure reported");ok(bad.ready==0,"failed init never publishes input");invalid.close();await(()->FakeGpu.activeContexts.get()==0,"failed init contexts cleaned");
  FakeGpu.reset();for(int n=0;n<20;n++){Callback cb=new Callback();E01GlOutput out=new E01GlOutput(new Context(),new Surface(),cb);out.close();}await(()->FakeGpu.activeContexts.get()==0,"rapid create-close cleans contexts");Thread.sleep(100);long threads=Thread.getAllStackTraces().keySet().stream().filter(t->t.isAlive()&&t.getName().startsWith("06Link-GL-")).count();ok(threads==0,"no GL worker leak after repeated lifecycle");
  System.out.println("PASS "+checks+" GL bridge threading/fence/lifecycle checks (real Java workers, fake EGL/GPU; not device FPS)");
 }
}
